import { useState } from 'react';import { Alert,Pressable,StyleSheet,Text,View } from '@/platform/react-native';import { router } from '@/router';import { useMutation,useQuery,useQueryClient } from '@tanstack/react-query';import { Ionicons } from '@/platform/icons';import { api } from '@/lib/api';import { Button,Card,EmptyState,Header,Input,Muted,Screen,useAppTheme } from '@/components/UI';import {CountryPhoneField} from '@/components/CountryPhoneField';
export default function TrustedContacts(){const{palette}=useAppTheme();const qc=useQueryClient();const[name,setName]=useState('');const[phone,setPhone]=useState('');const[relationship,setRelationship]=useState('');const{data=[]}=useQuery<any[]>({queryKey:['trusted-contacts'],queryFn:async()=>(await api.get('/trusted-contacts')).data});const add=useMutation({mutationFn:async()=>api.post('/trusted-contacts',{name,phone,relationship:relationship||undefined}),onSuccess:()=>{setName('');setPhone('');setRelationship('');qc.invalidateQueries({queryKey:['trusted-contacts']});Alert.alert('Trusted contact added','This contact is stored for your CDA Connect emergency workflow.')}});return <Screen scroll><Header title="Trusted Contacts" right={<Pressable onPress={()=>(router.canGoBack()?router.back():router.replace('/'))}><Ionicons name="close" size={26} color={palette.text}/></Pressable>}/><Muted>Trusted contacts are private to your account and are not shown in community discovery.</Muted><Card><Input placeholder="Name" value={name} onChangeText={setName}/><CountryPhoneField value={phone} onChange={setPhone}/><Input placeholder="Relationship" value={relationship} onChangeText={setRelationship}/><Button title="Add Trusted Contact" onPress={()=>add.mutate()} loading={add.isPending} disabled={name.length<2||phone.length<7}/></Card>{data.length?data.map(c=><Card key={c.Id}><Text style={[s.name,{color:palette.text}]}>{c.Name}</Text><Muted>{c.Relationship||'Trusted contact'} · {c.Phone}</Muted></Card>):<EmptyState icon="heart-outline" title="No trusted contacts" body="Add someone you trust so your emergency settings are ready before they are needed."/>}</Screen>}
const s=StyleSheet.create({name:{fontSize:16,fontWeight:'900'}})
